import { AfterViewInit, Component, computed, input, output, signal, viewChild, WritableSignal } from "@angular/core";
import { IBodySettings, ICallbackItem, IInputEnter, IColumnConfig, IInputChange } from "hwmx-angular/interfaces";
import { WIATextBox } from "../../wia-textbox/wia-textbox.component";
import { WIASelectBox } from "../../wia-selectbox/wia-selectbox.component";
import { WIANumberBox } from "../../wia-numberbox/wia-numberbox.component";
import { Tools } from "hwmx-angular/tools";

@Component({
    selector: 'wia-grid-cell',
    templateUrl: './wia-grid-cell.component.html',
    styleUrl: './wia-grid-cell.component.scss',
    standalone: false
})
export class WIAGridCell<T> implements AfterViewInit {

    //Elements   
    protected readonly WIATextBox   = viewChild<WIATextBox>('inputTextbox');
    protected readonly coerNumberbox = viewChild<WIANumberBox>('inputNumberbox');
    protected readonly coerSelectbox = viewChild<WIASelectBox<T>>('coerSelectbox');
    //protected readonly coerDatebox   = viewChild<WIADateBox>('inputDatebox');
   
    //Variables
    protected readonly _isElementReady = signal<boolean>(false);

    //Inputs 
    public readonly id             = input.required<string>();
    public readonly ApplyFormat    = input.required<(value: any, format: 'string' | 'number' | 'currency' | 'date' | 'datetime' | 'time') => string>();
    public readonly column         = input.required<IColumnConfig<T>>();
    public readonly row            = input.required<any>();
    public readonly bodySettings   = input.required<IBodySettings<T>>();
    public readonly isLoadingInner = input.required<WritableSignal<boolean>>();
    public readonly isEnabled      = input.required<boolean>();
    public readonly isDraging      = input.required<boolean>();
    public readonly isDragoverself = input.required<boolean>();
    public readonly isDragoverUp   = input.required<boolean>();
    public readonly isDragoverDown = input.required<boolean>();

    //Outputs  
    protected readonly onClickRow       = output<T>();
    protected readonly onDoubleClickRow = output<T>(); 
    protected readonly onInputChange    = output<IInputChange<T>>();
    protected readonly onKeyupEnter     = output<IInputEnter<T>>();
    protected readonly onUpdateType     = output<IInputChange<T>>();  


    ngAfterViewInit(): void { 
        Tools.Sleep(1000).then(() => this._isElementReady.set(true));
    }  


    //Function
    protected _DoubleClick(): void { 
        if(this.isEnabled()) {
            const ROW = { ...this.row() };
            delete ROW['__index__'];
            delete ROW['__checked__'];
 
            this.onDoubleClickRow.emit(ROW);
        }         
    }  


    /** */
    public _input = computed<'inputTextbox' | 'inputNumberbox' | 'inputSelectbox' | 'inputDatebox' | 'inputSwitch'>(() => {
        const COLUMN_CONFIG = this.column().config;
        if(Tools.IsNull(COLUMN_CONFIG?.template)) {
            if(this._ShowInput(COLUMN_CONFIG?.inputSwitch)) {
                return 'inputSwitch';
            }

            else if(this.isEnabled()) {
                if(this._ShowInput(COLUMN_CONFIG?.inputTextbox)) {
                    return 'inputTextbox';
                }
        
                else if(this._ShowInput(COLUMN_CONFIG?.inputNumberbox)) {
                    return 'inputNumberbox';
                }
        
                else if(this._ShowInput(COLUMN_CONFIG?.inputSelectbox)) {
                    return 'inputSelectbox';
                } 

                else if(this._ShowInput(COLUMN_CONFIG?.inputDatebox)) {
                    return 'inputDatebox';
                } 
            } 
        }

        return 'HTML' as any;
    });


    //Computed
    private _ShowInput = (property?: null | boolean | ((item: ICallbackItem<T>) => any)): boolean => { 
        const row = { ...this.row() };
        delete row['__index__'];
        delete row['__checked__'];

        return Tools.IsBooleanTrue(property) || (
            Tools.IsFunction(property) && (property as any)({
                property: this.column().config.property, 
                row, 
                value: row[this.column().config.property] 
            })?.showInput  
        );
    } 


    //Computed
    protected _GetCellValue = computed<string>(() => {  
        const value = (this.row() as any)[this.column().config.property] || ''; 
        
        //Template
        if(Tools.IsNotOnlyWhiteSpace(this.column()?.config?.template)) {  
            const ROW = { ...this.row() };
            delete ROW['__index__'];
            delete ROW['__checked__'];

            return Tools.IsFunction(this.column().config.template)              
                ? (this.column().config as any).template({ 
                    property: this.column().config.property,
                    row: ROW,
                    value
                }) 
                : this.column().config.template
        }

        return this.ApplyFormat()(value, this.column().config.format!); 
    }); 


    //Function
    protected _GetAttributes = () => { 
        const FUNCTION = (this.column().config as any)[this._input()]; 
        const ROW = { ...this.row() };
        delete ROW['__index__'];
        delete ROW['__checked__'];

        return (
            Tools.IsFunction(FUNCTION) && FUNCTION({
                property: this.column().config.property, 
                row: ROW, 
                value: ROW[this.column().config.property] 
            })
        ) || null;
    } 


    //Function
    protected _GetAttributeValue = (attribute: string, defaultValue: any = null): any => {  
        return Tools.IsNotNull(this._GetAttributes()) 
            ? (Tools.IsNotOnlyWhiteSpace(this._GetAttributes()[attribute]) ? this._GetAttributes()[attribute] : defaultValue)
            : defaultValue;
    } 


    //Computed
    protected _minHeight = computed<string>(() => {
        const BORDERS = !Tools.IsBooleanFalse(this.bodySettings().showBorders) ? '0.800px' : '0px';
        return `calc(${this.column().config.height!} - ${BORDERS})`
    });


    //Computed
    protected _GetTextAlignX = computed<'flex-start' | 'center' | 'flex-end'>(() => {
        switch(this.column().config.textAlignX!) {
            case 'left'  : return 'flex-start';
            case 'center': return 'center';
            case 'right' : return 'flex-end'; 
        }
    }); 


    //Computed
    protected _GetTextBreak = computed<'break-word' | 'keep-all'>(() => {
        return this.column().config.textBreak!
            ? 'break-word' : 'keep-all';
    });


    //Computed
    protected _GetSpaceBreak = computed<'nowrap' | 'normal'>(() => {
        return this.column().config.textBreak!
            ? 'normal' : 'nowrap';
    });


    //Computed
    protected _GetTextColor = computed(() => { 
        let color: any = this.column().config?.color;

        if(Tools.IsNotNull(color)) {
            if(Tools.IsFunction(color)) { 
                const ROW = { ...this.row() };
                delete ROW['__index__'];
                delete ROW['__checked__'];
    
                color = color({
                    property: this.column().config.property, 
                    row: ROW, 
                    value: ROW[this.column().config.property] 
                }) || null;
            }
    
            if(Tools.IsNotOnlyWhiteSpace(color)) {
                return `color-${color} font-weight-bold`;
            }
        }

        return '';
    });


    //Computed
    protected _GetBackground = computed(() => { 
        let background: any = this.column().config?.background;

        if(Tools.IsNotNull(background)) {
            if(Tools.IsFunction(background)) { 
                const ROW = { ...this.row() };
                delete ROW['__index__'];
                delete ROW['__checked__'];
    
                background = background({
                    property: this.column().config.property, 
                    row: ROW, 
                    value: ROW[this.column().config.property] 
                }) || null;
            }
    
            if(Tools.IsNotOnlyWhiteSpace(background)) {
                return `background-color-${background}`;
            }
        }

        return '';
    });


    /** */
    public Focus(onlyFocus: boolean = false): void {
        switch(this._input()) {
            case 'inputTextbox': {
                this.WIATextBox()?.Focus(onlyFocus);
                break;
            }

            case 'inputNumberbox': { 
                this.coerNumberbox()?.Focus(onlyFocus);
                break;
            }

            case 'inputSelectbox': { 
                this.coerSelectbox()?.Focus(!onlyFocus);
                break;
            }

            case 'inputDatebox': { 
                //Tools.Sleep(100).then(_ => this.coerDatebox());
                break;
            }
        }
    }


    /** */
    protected _SelectboxChange(value: any): void { 
        if(this._isElementReady()) {
            this.onInputChange.emit({
                position: 'BODY',
                input: this._input(),
                property: this.column().config.property,
                before: this.row(),
                value
            });
        }
        
        else if(`${value}` != `${this.row()[this.column().config.property]}`) {
            this.onUpdateType.emit({
                position: 'BODY',
                input: this._input(),
                property: this.column().config.property,
                before: this.row(),
                value
            }); 
        }
    }
}